#!/usr/bin/env bash
######################################################################
# .what = a fixture rule that blocks a payload which holds `deny`
######################################################################
set -euo pipefail
payload=$(cat)
if [[ "$payload" == *deny* ]]; then
  echo "" >&2
  echo "✋ ConstraintError: block.sh refuses $*" >&2
  echo "   └─ hint: drop the word deny" >&2
  echo "" >&2
  exit 2
fi
echo "block.sh passed"
